const fs=require('node:fs'),path=require('node:path');module.exports=function(entry){const files=['core','render',entry];return `(function(){const modules={${files.map(name=>JSON.stringify('./'+name)+':function(module,exports,require){\n'+fs.readFileSync(path.join(__dirname,'../src',name+'.js'),'utf8')+'\n}').join(',')}};const cache={};function require(id){if(cache[id])return cache[id].exports;const m=cache[id]={exports:{}};modules[id](m,m.exports,require);return m.exports;}require('./${entry}');})();`;};
